def get_rule_domain(rule: Rule) -> str:
    """Return the domain the rule matches on, combining the configured
    server name with the rule's host or subdomain.
    """
    if rule.host:
        return rule.host

    server_name = current_app.config["SERVER_NAME"]

    if not server_name:
        return ""

    if rule.subdomain:
        return f"{rule.subdomain}.{server_name}"

    return server_name


